 "view-backup": "<div class=\"view\" id=\"view-backup\">\n      <div class=\"view-head\">\n        <div>\n          <p class=\"brand-eyebrow\">Data safety</p>\n          <h1>Backup &amp; restore</h1>\n          <p class=\"sub\">Keep a copy of everything, or bring an old copy back.</p>\n        </div>\n      </div>\n      <div class=\"panel-box\">\n        <h2>Download a backup</h2>\n        <p class=\"sub\" style=\"margin-bottom:10px;\">Saves everything as one .json file: customers, contacts and interaction history, sales documents, payments, tasks, outreach, attendance, users, branches, lists, numbering, watermark and logos.</p>\n        <div id=\"backupSummary\" style=\"margin-bottom:10px;\"></div>\n        <button class=\"btn\" id=\"backupBtn\">Download backup</button>\n        <p class=\"field-hint\" id=\"backupHint\"></p>\n      </div>\n      <div class=\"panel-box\">\n        <h2>Restore from a backup</h2>\n        <p class=\"sub\" style=\"margin-bottom:14px;\">This replaces all current data with what's in the file. Admins only.</p>\n        <input type=\"file\" id=\"restoreFileInput\" accept=\".json\">\n        <div style=\"margin-top:12px;\"><button class=\"btn\" id=\"restoreBtn\">Restore</button></div>\n        <p class=\"field-hint\" id=\"restoreHint\"></p>\n      </div>\n    </div>",
